using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;

namespace MessageQueue.Consumer
{
    public sealed class AuditContext : IDisposable
    {
        private string _correlationId;
        private byte[] _buffer;
        private bool _disposed;

        public AuditContext(string correlationId, int bufferSize)
        {
            _correlationId = correlationId;
            _buffer = new byte[bufferSize];
            _disposed = false;
        }

        public string CorrelationId => _disposed ? throw new ObjectDisposedException(nameof(AuditContext)) : _correlationId;
        public Span<byte> Buffer => _buffer.AsSpan();
        public bool IsValid => !_disposed;

        public void WriteAuditEntry(string message)
        {
            if (_disposed) throw new ObjectDisposedException(nameof(AuditContext));
            var entry = System.Text.Encoding.UTF8.GetBytes($"[{_correlationId}] {message}");
            if (entry.Length <= _buffer.Length)
                Array.Copy(entry, _buffer, entry.Length);
        }

        public void Dispose()
        {
            _disposed = true;
            _buffer = null;
            _correlationId = null;
        }
    }

    public class MessageEnvelope
    {
        public string Id { get; set; }
        public string Payload { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public class ProcessingPipeline
    {
        private readonly ConcurrentDictionary<string, AuditContext> _activeContexts = new();
        private readonly ConcurrentQueue<Func<Task>> _pendingCallbacks = new();
        private readonly SemaphoreSlim _processingGate = new(1, 1);
        private readonly int _maxConcurrency;

        public ProcessingPipeline(int maxConcurrency = 4)
        {
            _maxConcurrency = maxConcurrency;
        }

        public async Task EnqueueMessageAsync(MessageEnvelope envelope)
        {
            if (envelope == null) throw new ArgumentNullException(nameof(envelope));
            if (string.IsNullOrEmpty(envelope.Id)) throw new ArgumentException("Envelope Id must be provided.", nameof(envelope));

            var context = new AuditContext(envelope.Id, 4096);
            _activeContexts.TryAdd(envelope.Id, context);

            var payload = envelope.Payload ?? string.Empty;
            context.WriteAuditEntry($"Message received: {payload.Substring(0, Math.Min(50, payload.Length))}");

            var callbackContext = context;
            _pendingCallbacks.Enqueue(async () =>
            {
                await ProcessWithAuditAsync(callbackContext, envelope);
            });

            await DrainCallbacksAsync();
        }

        private async Task DrainCallbacksAsync()
        {
            await _processingGate.WaitAsync();
            try
            {
                while (_pendingCallbacks.TryDequeue(out var callback))
                {
                    await callback();
                }
            }
            finally
            {
                _processingGate.Release();
            }
        }

        private async Task ProcessWithAuditAsync(AuditContext auditCtx, MessageEnvelope envelope)
        {
            try
            {
                await Task.Delay(10); // simulate I/O
                auditCtx.WriteAuditEntry("Processing started");

                var result = await TransformPayloadAsync(envelope.Payload ?? string.Empty);

                auditCtx.WriteAuditEntry($"Transform complete: {result.Length} bytes");
                await CommitResultAsync(envelope.Id, result, auditCtx);
            }
            catch (ObjectDisposedException)
            {
                // Swallowed - context was already cleaned up
            }
        }

        private async Task<string> TransformPayloadAsync(string payload)
        {
            await Task.Delay(5);
            return Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(payload ?? string.Empty));
        }

        private async Task CommitResultAsync(string messageId, string result, AuditContext ctx)
        {
            await Task.Delay(5);
            ctx.WriteAuditEntry("Commit successful");

            // Release context after commit
            if (_activeContexts.TryRemove(messageId, out var removed))
            {
                removed.Dispose();
            }
        }

        public async Task ReprocessFailedAsync(string messageId, string newPayload)
        {
            if (string.IsNullOrEmpty(messageId)) throw new ArgumentException("messageId must be provided.", nameof(messageId));

            // Create a fresh audit context for reprocessing to avoid use-after-dispose
            var freshContext = new AuditContext(messageId, 4096);
            _activeContexts.AddOrUpdate(messageId, freshContext, (_, old) => { old.Dispose(); return freshContext; });

            var envelope = new MessageEnvelope
            {
                Id = messageId,
                Payload = newPayload,
                Timestamp = DateTime.UtcNow
            };

            // Schedule reprocessing with the fresh context
            _pendingCallbacks.Enqueue(async () =>
            {
                await ProcessWithAuditAsync(freshContext, envelope);
            });

            await DrainCallbacksAsync();
        }
    }

    public class QueueConsumerService
    {
        private readonly ProcessingPipeline _pipeline;
        private readonly CancellationTokenSource _cts;

        public QueueConsumerService()
        {
            _pipeline = new ProcessingPipeline();
            _cts = new CancellationTokenSource();
        }

        public async Task ConsumeAsync(Func<Task<MessageEnvelope>> messageSource)
        {
            if (messageSource == null) throw new ArgumentNullException(nameof(messageSource));

            while (!_cts.Token.IsCancellationRequested)
            {
                var message = await messageSource();
                if (message == null) break;

                await _pipeline.EnqueueMessageAsync(message);
            }
        }

        public async Task RetryMessageAsync(string id, string payload)
        {
            await _pipeline.ReprocessFailedAsync(id, payload);
        }

        public void Stop() => _cts.Cancel();
    }
}
